                        "zikfxwvv": {
                            "type": "html-box",
                            "specials": {
                                "customAdvance": true,
                                "html": "&lt;!-- ⭐ CHỈNH NGÀY &amp; NGÔN NGỮ Ở ĐÂY --&gt;\r\n&lt;script&gt;\r\n  const DATE_INPUT = &quot;16,17.01.2027&quot;;  \r\n  const CAL_LANG   = &quot;vi&quot;; // &quot;vi&quot; hoặc &quot;en&quot;\r\n&lt;/script&gt;\r\n\r\n&lt;div class=&quot;wc-cal-outer&quot;&gt;\r\n\r\n  &lt;!-- TIÊU ĐỀ --&gt;\r\n  &lt;div id=&quot;wc-cal-title&quot; class=&quot;wc-cal-title&quot;&gt;THÁNG …&lt;/div&gt;\r\n\r\n  &lt;div class=&quot;wc-cal&quot; id=&quot;wc-cal-target&quot;&gt;\r\n    &lt;div class=&quot;wc-cal-frame&quot;&gt;\r\n      &lt;div class=&quot;wc-cal-grid&quot; data-cal-grid&gt;&lt;/div&gt;\r\n    &lt;/div&gt;\r\n  &lt;/div&gt;\r\n\r\n&lt;/div&gt;\r\n\r\n&lt;style&gt;\r\n  /* 👉 Thêm Google Fonts giống các code trước */\r\n  @import url(&#039;https://fonts.googleapis.com/css2?family=Kaisei+Decol:wght@400;700&amp;family=Open+Sans:wght@400;700&amp;display=swap&#039;);\r\n\r\n  .wc-cal-outer{\r\n    width:100%;\r\n    display:flex;\r\n    flex-direction:column;\r\n    align-items:center;\r\n    padding:0;\r\n  }\r\n\r\n  /* 👉 Tiêu đề dùng Kaisei Decol cho đồng bộ */\r\n  .wc-cal-title{\r\n    font-family:&quot;Kaisei Decol&quot;, serif;\r\n    font-size:22px;\r\n    text-align:center;\r\n    margin-bottom:10px;\r\n  }\r\n\r\n  .wc-cal{\r\n    width:100%;\r\n    max-width:340px;\r\n  }\r\n\r\n  .wc-cal-frame{\r\n    border:1px solid #c00000;\r\n    padding:14px 16px;\r\n    box-sizing:border-box;\r\n  }\r\n\r\n  .wc-cal-grid{\r\n    display:grid;\r\n    grid-template-columns:repeat(7, 1fr);\r\n    gap:10px;\r\n  }\r\n\r\n  .wc-cal-grid &gt; div{\r\n    min-height:32px;\r\n    display:flex;\r\n    align-items:center;\r\n    justify-content:center;\r\n    position:relative;\r\n  }\r\n\r\n  /* 👉 Hàng thứ dùng Open Sans (giống các code trước) */\r\n  .wc-cal-dow{\r\n    font-family:&quot;Open Sans&quot;, sans-serif;\r\n    font-weight:700;\r\n    font-size:14px;\r\n  }\r\n\r\n  /* 👉 Ô ngày cũng dùng Open Sans */\r\n  .wc-cal-day{\r\n    font-family:&quot;Open Sans&quot;, sans-serif;\r\n    font-weight:400;\r\n    font-size:14px;\r\n    position:relative;\r\n  }\r\n\r\n  .wc-cal-day-span{\r\n    position:relative;\r\n    z-index:2;\r\n  }\r\n\r\n  .wc-cal-day--sun .wc-cal-day-span{\r\n    font-weight:700;\r\n  }\r\n\r\n  .wc-cal-day--selected .wc-cal-day-span{\r\n    font-weight:700;\r\n  }\r\n\r\n  .wc-cal-empty{\r\n    opacity:0;\r\n  }\r\n\r\n  .wc-cal-heart{\r\n    position:absolute;\r\n    width:40px;\r\n    height:40px;\r\n    top:calc(50% + 0px);\r\n    left:50%;\r\n    transform:translate(-50%, -50%);\r\n    z-index:1;\r\n    pointer-events:none;\r\n    animation:heartFlash 4s infinite ease-in-out;\r\n  }\r\n\r\n  @keyframes heartFlash{\r\n    0%,100%{opacity:1; transform:translate(-50%,-50%) scale(1);}\r\n    50%{opacity:0.3; transform:translate(-50%,-50%) scale(1.15);}\r\n  }\r\n&lt;/style&gt;\r\n\r\n&lt;script&gt;\r\n(function(){\r\n  const HEART_SRC =\r\n    &quot;images/016.png&quot;;\r\n\r\n  const titleEl = document.getElementById(&quot;wc-cal-title&quot;);\r\n  const cal = document.getElementById(&quot;wc-cal-target&quot;);\r\n  if(!cal || !titleEl) return;\r\n  const gridEl = cal.querySelector(&quot;[data-cal-grid]&quot;);\r\n\r\n  const dowsVi = [&quot;T2&quot;,&quot;T3&quot;,&quot;T4&quot;,&quot;T5&quot;,&quot;T6&quot;,&quot;T7&quot;,&quot;CN&quot;];\r\n  const dowsEn = [&quot;SUN&quot;,&quot;MON&quot;,&quot;TUE&quot;,&quot;WED&quot;,&quot;THU&quot;,&quot;FRI&quot;,&quot;SAT&quot;];\r\n\r\n  const monthFullEn = [\r\n    &quot;JANUARY&quot;,&quot;FEBRUARY&quot;,&quot;MARCH&quot;,&quot;APRIL&quot;,&quot;MAY&quot;,&quot;JUNE&quot;,\r\n    &quot;JULY&quot;,&quot;AUGUST&quot;,&quot;SEPTEMBER&quot;,&quot;OCTOBER&quot;,&quot;NOVEMBER&quot;,&quot;DECEMBER&quot;\r\n  ];\r\n\r\n  function renderCalendar(days, month, year){\r\n    if(!gridEl) return;\r\n\r\n    // ⭐ TIÊU ĐỀ (ENGLISH ALL CAPS)\r\n    if (CAL_LANG === &quot;en&quot;) {\r\n      titleEl.textContent = monthFullEn[month - 1] + &quot; - &quot; + year;\r\n    } \r\n    // ⭐ TIÊU ĐỀ VIỆT\r\n    else {\r\n      titleEl.textContent = &quot;THÁNG &quot; + month + &quot; - &quot; + year;\r\n    }\r\n\r\n    gridEl.innerHTML = &quot;&quot;;\r\n\r\n    const dows = (CAL_LANG === &quot;en&quot;) ? dowsEn : dowsVi;\r\n    dows.forEach(d=&gt;{\r\n      const div = document.createElement(&quot;div&quot;);\r\n      div.className=&quot;wc-cal-dow&quot;;\r\n      div.textContent=d;\r\n      gridEl.appendChild(div);\r\n    });\r\n\r\n    const first = new Date(year, month - 1, 1);\r\n    const total = new Date(year, month, 0).getDate();\r\n\r\n    let offset, isSundayColFn;\r\n\r\n    if (CAL_LANG === &quot;en&quot;) {\r\n      offset = first.getDay(); // 0=Sun..6=Sat\r\n      isSundayColFn = col =&gt; col === 0;\r\n    } else {\r\n      offset = (first.getDay() + 6) % 7;\r\n      isSundayColFn = col =&gt; col === 6;\r\n    }\r\n\r\n    for(let i=0;i&lt;offset;i++){\r\n      const empty = document.createElement(&quot;div&quot;);\r\n      empty.className=&quot;wc-cal-day wc-cal-empty&quot;;\r\n      gridEl.appendChild(empty);\r\n    }\r\n\r\n    for(let d=1; d&lt;=total; d++){\r\n      const cell = document.createElement(&quot;div&quot;);\r\n      cell.className=&quot;wc-cal-day&quot;;\r\n\r\n      const index = offset + (d - 1);\r\n      const col = index % 7;\r\n\r\n      if (isSundayColFn(col)) {\r\n        cell.classList.add(&quot;wc-cal-day--sun&quot;);\r\n      }\r\n\r\n      const span = document.createElement(&quot;span&quot;);\r\n      span.className=&quot;wc-cal-day-span&quot;;\r\n      span.textContent=d;\r\n      cell.appendChild(span);\r\n\r\n      if(days.includes(d)){\r\n        cell.classList.add(&quot;wc-cal-day--selected&quot;);\r\n        const img = document.createElement(&quot;img&quot;);\r\n        img.src = HEART_SRC;\r\n        img.className = &quot;wc-cal-heart&quot;;\r\n        cell.appendChild(img);\r\n      }\r\n\r\n      gridEl.appendChild(cell);\r\n    }\r\n  }\r\n\r\n  function parseInput(str){\r\n    const match = str.match(/^([\\d,\\s]+)[\\/\\.\\-](\\d{1,2})[\\/\\.\\-](\\d{4})$/);\r\n    if(!match) return;\r\n\r\n    const dayList = match[1]\r\n      .split(&quot;,&quot;)\r\n      .map(x =&gt; parseInt(x.trim(), 10))\r\n      .filter(x =&gt; !isNaN(x));\r\n\r\n    const month = parseInt(match[2],10);\r\n    const year  = parseInt(match[3],10);\r\n\r\n    renderCalendar(dayList, month, year);\r\n  }\r\n\r\n  parseInput(DATE_INPUT || &quot;&quot;);\r\n\r\n})();\r\n&lt;/script&gt;\r\n"
                            },
                            "id": "zikfxwvv",
                            "$parent": "frfn2a1z"
                        },
